package it.carmine.streamplayer;
import android.app.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.ActivityController;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={31,35}) public class EventSettingsTest {
 @Test public void longPressEditsPersistentSportsUrlAndCanReset(){try(ActivityController<StartupTest.OfflineActivity> c=Robolectric.buildActivity(StartupTest.OfflineActivity.class).setup()){
 Activity a=c.get();assertTrue(a.getWindow().getDecorView().findViewWithTag("navEvents").performLongClick());Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();EditText input=d.getWindow().getDecorView().findViewWithTag("eventsHomeInput");input.setText("http://bad.example");d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertTrue(d.isShowing());assertNotNull(input.getError());input.setText("new-sports.example/prog.txt");d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertEquals("https://new-sports.example/prog.txt",EventSettings.home(a));assertEquals(EventSettings.home(a),EventSource.scheduleUrl(EventSettings.home(a)));EventSettings.edit(a);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();d.getButton(AlertDialog.BUTTON_NEUTRAL).performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(EventSource.HOME,EventSettings.home(a));assertEquals("https://sports.example/prog.txt",EventSource.scheduleUrl("https://sports.example/"));
 }}
 @Test public void changingDomainInvalidatesPreviousCatalogue()throws Exception{android.content.Context c=RuntimeEnvironment.getApplication();org.json.JSONObject j=new org.json.JSONObject().put("data",EventSourceTest.FEED).put("home",EventSource.HOME).put("fetchedAt",1);java.io.File file=new java.io.File(c.getFilesDir(),"sportsonline-schedule.json");java.nio.file.Files.write(file.toPath(),j.toString().getBytes("UTF-8"));assertNotNull(new EventSource(c).cached());EventSettings.save(c,"https://new.example/");assertFalse(file.exists());java.nio.file.Files.write(file.toPath(),j.toString().getBytes("UTF-8"));assertNull(new EventSource(c).cached());}
}
